#include <stdio.h>

typedef long long ll;
typedef __int128 lll;

static inline lll prefix_sum(ll k, ll A) {
    return (lll)k * (2LL * A + k - 1) / 2;
}

int main(void) {
    int P;
    scanf("%d", &P);

    while (P--) {
        ll L, A, B;
        scanf("%lld %lld %lld", &L, &A, &B);

        ll n = B - A + 1;

        if (prefix_sum(n, A) < L) {
            printf("%lld\n", n);
            continue;
        }

        ll lo = 1, hi = n;
        while (lo < hi) {
            ll mid = lo + (hi - lo) / 2;
            if (prefix_sum(mid, A) >= L)
                hi = mid;
            else
                lo = mid + 1;
        }

        printf("%lld\n", lo);
    }

    return 0;
}
